/* Print-time page orientation for regular invoices. */
let activeInvoiceOrientation='portrait';
let activeInvoiceKey='',activeInvoiceId='';
function invoicePageLayoutControl(){let controls=$('#modalBody .invoiceFormatControls');if(!controls||controls.querySelector('#invoicePageOrientation'))return;let label=document.createElement('label');label.className='invoiceStyleChoice';label.innerHTML='<span>Page Layout </span><select id="invoicePageOrientation" aria-label="Invoice page layout"><option value="portrait">Portrait</option><option value="landscape">Landscape</option></select>';controls.appendChild(label);let select=$('#invoicePageOrientation');select.value=activeInvoiceOrientation;select.onchange=()=>activeInvoiceOrientation=select.value}
function printInvoiceWithPageLayout(){let template=selectedTemplate?.('regular',activeInvoiceKey,activeInvoiceId),layout=template?.layout||customLayout('regular'),paper=invoicePaperSizes.find(p=>p.id===supportedInvoicePaper(activeInvoicePaper))||invoicePaperSizes[0],width=Number(paper.width),height=Number(paper.height),margin=layout?.enabled?Number(layout.margin):10;if(activeInvoiceOrientation==='landscape')[width,height]=[height,width];clearInvoicePrintMode();let style=document.createElement('style');style.id='a4PageSize';style.textContent='@media print{@page{size:'+width+'mm '+height+'mm;margin:'+margin+'mm}body.printingA4 .invoice{width:100%!important;max-width:'+(width-2*margin)+'mm!important}}';document.head.appendChild(style);document.body.classList.add('printingA4');let cleanup=()=>{clearInvoicePrintMode();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);try{window.print()}catch{cleanup();toast('Use the browser print menu to check page layout and print.')}}
const invoiceBeforePageLayout=invoice;
invoice=function(key,id,paper){activeInvoiceKey=key;activeInvoiceId=id;activeInvoiceOrientation='portrait';invoiceBeforePageLayout(key,id,paper);invoicePageLayoutControl();for(let button of $$('#modalBody [data-action="print"],#modalBody #printInvoice,#modalBody [data-fullPaperPrint]')){button.removeAttribute('data-action');button.onclick=printInvoiceWithPageLayout}};
printA4Invoice=printInvoiceWithPageLayout;
